<script setup lang="ts">
import IpPolicySummary from "../components/IpPolicySummary.vue";
import PlanIpAllowance from "../components/PlanIpAllowance.vue";
import CustomerCheckoutModal from "../components/CustomerCheckoutModal.vue";
import CustomerRenewalEligibility from "../components/CustomerRenewalEligibility.vue";
import CustomerLoyalty from "../components/CustomerLoyalty.vue";
import TrialOffer from "../components/trials/TrialOffer.vue";
import { ref, onMounted, onUnmounted, watch } from "vue";
import { useRouter, useRoute } from "vue-router";
import { useCustomerAuth } from "@papilio/auth";
import { ApiError, request, item, query, type CheckoutIntent, type CustomerPriceQuote, type Page, type Topup, type Plan, type PaymentDestination, type AccountPreferences, type Subscription, type AccountDelivery, type WalletEntry } from "@papilio/api";
import NumField from "@papilio/ui/NumField.vue";
import { toman, faNumber, faDate, asciiDigits } from "@papilio/ui";
import TopupEvidence from "../components/TopupEvidence.vue";
const auth=useCustomerAuth(); const router=useRouter();const route=useRoute();let linkedVersion=0; const tab=ref<"wallet"|"plans"|"subscriptions"|"ledger">("wallet"); const error=ref(""); const notice=ref(""); const busy=ref(false); const preferences=ref<AccountPreferences|null>(null); const balance=ref<number|null>(null); const amount=ref(""); const topupKey=ref(crypto.randomUUID()); const purchaseKey=ref(crypto.randomUUID());
const checkoutOpen=ref(false),checkoutId=ref<number|null>(null);const checkoutFilter=ref<CheckoutIntent["state"]|"">("");const checkouts=ref<CheckoutIntent[]>([]),checkoutPage=ref(1),checkoutPages=ref(1),checkoutState=ref<"idle"|"loading"|"ready"|"error">("idle");let checkoutVersion=0;
const topups=ref<Topup[]>([]);const topupPage=ref(1);const topupPages=ref(1);const topupState=ref<"loading"|"ready"|"error">("loading");const selectedTopup=ref<Topup|null>(null);
const destinations=ref<PaymentDestination[]>([]);const destinationPage=ref(1);const destinationPages=ref(1);const destinationQ=ref("");const destinationState=ref<"idle"|"loading"|"ready"|"error">("idle");const selectedDestination=ref<PaymentDestination|null>(null);
const plans=ref<Plan[]>([]);const planPage=ref(1);const planPages=ref(1);const planQ=ref("");const planState=ref<"idle"|"loading"|"ready"|"error">("idle");const selectedPlan=ref<Plan|null>(null);const selectedQuote=ref<CustomerPriceQuote|null>(null);const quoteBusy=ref(false);let quoteVersion=0;const autoRenew=ref(false);
const subscriptions=ref<Subscription[]>([]);const subscriptionPage=ref(1);const subscriptionPages=ref(1);const subscriptionState=ref<"idle"|"loading"|"ready"|"error">("idle");const selectedSubscription=ref<Subscription|null>(null);const delivery=ref<AccountDelivery|null>(null);
const ledger=ref<WalletEntry[]>([]);const ledgerPage=ref(1);const ledgerPages=ref(1);const ledgerState=ref<"idle"|"loading"|"ready"|"error">("idle");
let walletVersion=0,destinationVersion=0,planVersion=0,subscriptionVersion=0,ledgerVersion=0,deliveryVersion=0;let alive=true;
function fail(cause:unknown):void {error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}
async function loadWallet():Promise<void> {const stamp=++walletVersion;topupState.value="loading";try {const [wallet,prefs,rows]=await Promise.all([item<{balance_rial:number}>("/v1/customer/wallet"),item<AccountPreferences>("/v1/customer/preferences"),request<Page<Topup>>(`/v1/customer/topups?${query({page:topupPage.value})}`)]);if(!alive||stamp!==walletVersion)return;balance.value=wallet.balance_rial;preferences.value=prefs;topups.value=rows.data;topupPages.value=rows.meta.pager?.total_pages??1;topupState.value="ready";if(selectedTopup.value){ const id=selectedTopup.value.id;const fresh=await item<Topup>(`/v1/customer/topups/${id}`);if(alive&&stamp===walletVersion&&selectedTopup.value?.id===id)selectedTopup.value=fresh;}}catch(cause){if(stamp===walletVersion){topupState.value="error";fail(cause);}}}
async function loadDestinations():Promise<void> {const stamp=++destinationVersion;destinationState.value="loading";try{const rows=await request<Page<PaymentDestination>>(`/v1/customer/payment-destinations?${query({page:destinationPage.value,q:destinationQ.value})}`);if(!alive||stamp!==destinationVersion)return;destinations.value=rows.data;destinationPages.value=rows.meta.pager?.total_pages??1;destinationState.value="ready";}catch(cause){if(stamp===destinationVersion){destinationState.value="error";fail(cause);}}}
async function loadPlans():Promise<void>{const stamp=++planVersion;planState.value="loading";try{const rows=await request<Page<Plan>>(`/v1/customer/plans?${query({page:planPage.value,q:planQ.value})}`);if(!alive||stamp!==planVersion)return;plans.value=rows.data;planPages.value=rows.meta.pager?.total_pages??1;planState.value="ready";}catch(cause){if(stamp===planVersion){planState.value="error";fail(cause);}}}
async function loadSubscriptions():Promise<void>{const stamp=++subscriptionVersion;subscriptionState.value="loading";try{const rows=await request<Page<Subscription>>(`/v1/customer/subscriptions?${query({page:subscriptionPage.value})}`);if(!alive||stamp!==subscriptionVersion)return;subscriptions.value=rows.data;subscriptionPages.value=rows.meta.pager?.total_pages??1;subscriptionState.value="ready";}catch(cause){if(stamp===subscriptionVersion){subscriptionState.value="error";fail(cause);}}}
async function loadCheckouts():Promise<void>{const stamp=++checkoutVersion;checkoutState.value="loading";try{const result=await request<Page<CheckoutIntent>>(`/v1/customer/checkouts?${query({page:checkoutPage.value,state:checkoutFilter.value||undefined})}`);if(!alive||stamp!==checkoutVersion)return;checkouts.value=result.data;checkoutPages.value=result.meta.pager?.total_pages??1;checkoutState.value="ready";}catch(cause){if(alive&&stamp===checkoutVersion){checkoutState.value="error";fail(cause);}}}
function beginCheckout():void{if(!selectedPlan.value)return;checkoutId.value=null;checkoutOpen.value=true;}
function resumeCheckout(row:CheckoutIntent):void{checkoutId.value=row.id;checkoutOpen.value=true;}
function checkoutSaved(row:CheckoutIntent):void{checkoutId.value=row.id;void router.replace({query:{...route.query,checkout_id:String(row.id)}});void loadCheckouts();void loadWallet();}
async function loadLedger():Promise<void>{const stamp=++ledgerVersion;ledgerState.value="loading";try{const rows=await request<Page<WalletEntry>>(`/v1/customer/wallet/entries?${query({page:ledgerPage.value})}`);if(!alive||stamp!==ledgerVersion)return;ledger.value=rows.data;ledgerPages.value=rows.meta.pager?.total_pages??1;ledgerState.value="ready";}catch(cause){if(stamp===ledgerVersion){ledgerState.value="error";fail(cause);}}}
function switchTab(value:typeof tab.value):void{tab.value=value;error.value="";if(value==="wallet")void loadWallet();else if(value==="plans"){void loadPlans();void loadCheckouts();}else if(value==="subscriptions")void loadSubscriptions();else void loadLedger();}
async function topup():Promise<void>{busy.value=true;error.value="";notice.value="";try{const normalized=asciiDigits(amount.value).replace(/٫/g,".");if(!/^\d+(?:\.\d)?$/.test(normalized))throw new Error("Enter the amount in toman with at most one decimal place.");const rial=Math.round(Number(normalized)*10);if(!Number.isSafeInteger(rial)||rial<=0)throw new Error("Enter a valid amount.");selectedTopup.value=await item<Topup>("/v1/customer/topups","POST",{request_key:topupKey.value,amount_rial:rial,destination_id:preferences.value?.checkout.destination_mode==="legacy"?null:selectedDestination.value?.destination_id??null});topupKey.value=crypto.randomUUID();notice.value="Top-up requested. Payment details and receipt upload are shown below.";await loadWallet();}catch(cause){fail(cause);}finally{busy.value=false;}}
async function choosePlan(row:Plan):Promise<void>{if(busy.value)return;selectedPlan.value=row;selectedQuote.value=null;purchaseKey.value=crypto.randomUUID();notice.value="";await loadQuote(row.id);}
async function loadQuote(id:number):Promise<void>{const stamp=++quoteVersion;quoteBusy.value=true;selectedQuote.value=null;error.value="";try{const result=await item<CustomerPriceQuote>(`/v1/customer/plans/${id}/quote`);if(alive&&stamp===quoteVersion&&selectedPlan.value?.id===id)selectedQuote.value=result;}catch(cause){if(alive&&stamp===quoteVersion)fail(cause);}finally{if(stamp===quoteVersion)quoteBusy.value=false;}}
async function purchase():Promise<void>{if(!selectedPlan.value||!selectedQuote.value||quoteBusy.value)return;busy.value=true;error.value="";notice.value="";try{const result=await item<Subscription>("/v1/customer/subscriptions","POST",{plan_id:selectedPlan.value.id,expected_price_rial:selectedQuote.value.price_rial,auto_renew:autoRenew.value,purchase_key:purchaseKey.value});purchaseKey.value=crypto.randomUUID();selectedSubscription.value=result;notice.value=`Purchase #${faNumber(result.id)} submitted. You can track provisioning in My services.`;tab.value="subscriptions";await Promise.all([loadWallet(),loadSubscriptions()]);await showDelivery(result);}catch(cause){fail(cause);if(cause instanceof ApiError && cause.code==="purchase_price_changed" && selectedPlan.value){const id=selectedPlan.value.id;try{const fresh=await item<Plan>(`/v1/customer/plans/${id}`);if(alive&&selectedPlan.value?.id===id){selectedPlan.value=fresh;plans.value=plans.value.map(row=>row.id===id?fresh:row);selectedQuote.value=null;await loadQuote(id);}}catch(refresh){error.value+=" · "+(refresh instanceof Error?refresh.message:"Could not refresh the price.");}}}finally{busy.value=false;}}
async function showDelivery(row:Subscription):Promise<void>{selectedSubscription.value=row;delivery.value=null;const stamp=++deliveryVersion;try{const result=await item<AccountDelivery>(`/v1/customer/subscriptions/${row.id}/delivery`);if(alive&&stamp===deliveryVersion)delivery.value=result;}catch(cause){if(stamp===deliveryVersion)fail(cause);}}
async function renewal():Promise<void>{if(!selectedSubscription.value)return;busy.value=true;error.value="";try{const result=await item<Subscription>(`/v1/customer/subscriptions/${selectedSubscription.value.id}/auto-renew`,"PATCH",{enabled:!selectedSubscription.value.auto_renew});await showDelivery(result);await loadSubscriptions();}catch(cause){fail(cause);}finally{busy.value=false;}}
async function rotate():Promise<void>{if(!selectedSubscription.value)return;busy.value=true;error.value="";try{delivery.value=await item<AccountDelivery>(`/v1/customer/subscriptions/${selectedSubscription.value.id}/rotate-link`,"POST");notice.value="Previous URL revoked. Add the new URL to your VPN client.";}catch(cause){fail(cause);}finally{busy.value=false;}}
async function logout():Promise<void>{try{await auth.logout();await router.push("/account/sign-in");}catch(cause){fail(cause);}}
const statuses:Record<string,string>={customer_hold:"Service access suspended",active:"Active",pending_provision:"Pending provisioning",revoking:"Revoking",expired:"Expired",exhausted:"Quota exhausted",suspended:"Suspended",failed:"Failed",cancelled:"Cancelled"};
const reasons:Record<string,string>={approved_topup:"Top-up approved",purchase:"Service purchase",auto_renewal:"Renewal Automatic Service",provision_refund:"Failed purchase refund"};
function linkedId(value:unknown):number|undefined{if(typeof value!=="string"||!/^\d+$/.test(value))return undefined;const id=Number(value);return Number.isSafeInteger(id)&&id>0?id:undefined;}
async function openLinkedTopup(id:number,stamp:number):Promise<void>{try{const row=await item<Topup>(`/v1/customer/topups/${id}`);if(!alive||stamp!==linkedVersion)return;selectedTopup.value=row;switchTab("wallet");}catch(cause){if(alive&&stamp===linkedVersion)fail(cause);}}
async function openLinkedSubscription(id:number,stamp:number):Promise<void>{try{const row=await item<Subscription>(`/v1/customer/subscriptions/${id}`);if(!alive||stamp!==linkedVersion)return;switchTab("subscriptions");await showDelivery(row);}catch(cause){if(alive&&stamp===linkedVersion)fail(cause);}}
watch(()=>[route.query.topup_id,route.query.subscription_id,route.query.checkout_id],()=>{const stamp=++linkedVersion;deliveryVersion++;const ownedCheckoutId=linkedId(route.query.checkout_id);if(ownedCheckoutId!==undefined){checkoutId.value=ownedCheckoutId;checkoutOpen.value=true;}else if(checkoutId.value!==null){checkoutOpen.value=false;checkoutId.value=null;}const topupId=linkedId(route.query.topup_id);const subscriptionId=linkedId(route.query.subscription_id);if(topupId!==undefined)void openLinkedTopup(topupId,stamp);else if(subscriptionId!==undefined)void openLinkedSubscription(subscriptionId,stamp);},{immediate:true});
onMounted(()=>void loadWallet());onUnmounted(()=>{alive=false;deliveryVersion++;quoteVersion++;checkoutVersion++;});
</script>
<template><main class="customer-shell"><header class="page-head"><div><p class="eyebrow">{{ preferences?.brand_title || 'Customer account' }}</p><h1>{{ auth.session?.display_name }}</h1><p class="subtitle">Wallet balance: {{ balance===null ? 'Loading…' : toman(balance) }}</p></div><button class="btn secondary" @click="logout">Sign out</button></header><nav class="customer-tabs" aria-label="Account sections"><RouterLink class="btn secondary" to="/account/notifications">My notifications</RouterLink><RouterLink class="btn secondary" to="/account/support">Account support</RouterLink><button v-for="entry in ([['wallet','Wallet and payments'],['plans','Service purchase'],['subscriptions','My services'],['ledger','Wallet activity']] as const)" :key="entry[0]" class="btn" :class="{'secondary':tab!==entry[0]}" @click="switchTab(entry[0])">{{ entry[1] }}</button></nav><p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message" role="status">{{ notice }}</p>
<section v-if="tab==='wallet'" class="form-grid"><form class="card card-pad form-grid" @submit.prevent="topup"><h2>Request a wallet top-up</h2><p v-if="preferences?.payment_instructions">{{ preferences.payment_instructions }}</p><p v-if="preferences?.checkout">Allowed amount: {{ toman(preferences.checkout.minimum_topup_rial) }} to {{ toman(preferences.checkout.maximum_topup_rial) }}</p><NumField v-model="amount" label="Top-up amount (toman)" /><p>Create the request before transferring. Follow its saved exact RIAL amount, including any identifier digits.</p><div class="inline-actions"><button v-for="value in preferences?.topup_options_rial" :key="value" type="button" class="btn small secondary" @click="amount=String(value/10)">{{ toman(value) }}</button></div><section v-if="preferences?.checkout.destination_mode!=='legacy'" class="form-grid"><h3>Choose a payment destination</h3><p v-if="selectedDestination">Selected: {{ selectedDestination.title }} · {{ selectedDestination.recipient }}</p><div class="toolbar"><label class="field"><span>Search payment destinations</span><input v-model="destinationQ" @keydown.enter.prevent="destinationPage=1;loadDestinations()" /></label><button type="button" class="btn secondary" @click="destinationPage=1;loadDestinations()">Search destinations</button><button v-if="preferences?.checkout.destination_mode==='optional'" type="button" class="btn secondary" @click="selectedDestination=null">No destination selected</button></div><p v-if="destinationState==='loading'">Loading…</p><p v-else-if="destinationState==='ready' && !destinations.length">No payment destinations available.</p><div class="inline-actions"><button v-for="row in destinations" :key="row.destination_id" type="button" class="btn secondary" :aria-pressed="selectedDestination?.destination_id===row.destination_id" @click="selectedDestination=row">{{ row.title }} · {{ row.bank_name }}</button></div><div v-if="destinationState!=='idle'" class="pager"><button type="button" :disabled="destinationPage<=1" @click="destinationPage--;loadDestinations()">‹</button><span>{{ faNumber(destinationPage) }}</span><button type="button" :disabled="destinationPage>=destinationPages" @click="destinationPage++;loadDestinations()">›</button></div></section><button class="btn" :disabled="busy || !preferences || (preferences.checkout.destination_mode==='required'&&!selectedDestination)">Create top-up request</button></form><section class="card card-pad"><h2>My payments</h2><button class="btn secondary" @click="loadWallet">Refresh payments</button><p v-if="topupState==='loading'">Loading…</p><p v-else-if="topupState==='ready' && !topups.length">No top-up requests yet.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Payment</th><th>Amount</th><th>Status</th></tr></thead><tbody><tr v-for="row in topups" :key="row.id" tabindex="0" :class="{'selected-row':selectedTopup?.id===row.id}" @click="selectedTopup=row" @keydown.enter="selectedTopup=row"><td>{{ faNumber(row.id) }}</td><td class="tabular" dir="ltr">{{Number.isSafeInteger(row.amount_rial)?String(row.amount_rial)+' RIAL':'Exact amount unavailable'}}<small v-if="row.payment_identifier_code4!=null"> · Code {{row.payment_identifier_code4}}</small><br/><small>{{toman(row.amount_rial)}}</small></td><td>{{ row.status==='pending'?'Pending review':row.status==='approved'?'Approved':'Rejected' }}</td></tr></tbody></table></div><div class="pager"><button :disabled="topupPage<=1" @click="topupPage--;loadWallet()">‹</button><span>{{ faNumber(topupPage) }}</span><button :disabled="topupPage>=topupPages" @click="topupPage++;loadWallet()">›</button></div><RouterLink v-if="selectedTopup" class="btn secondary" :to="{path:'/account/support',query:{topup_id:selectedTopup.id}}">Get help with this payment</RouterLink><TopupEvidence v-if="selectedTopup" :key="selectedTopup.id" :topup-id="selectedTopup.id" :topup="selectedTopup" audience="customer" :pending="selectedTopup.status==='pending'" :can-upload="preferences?.receipts.enabled ?? false" /></section></section>
<CustomerLoyalty v-if="tab==='plans' && auth.session" :key="auth.session.customer_id" :customer-id="auth.session.customer_id" /><TrialOffer v-if="tab==='plans' && auth.session" :customer-id="auth.session.customer_id" can-claim /><section v-if="tab==='plans'" class="card card-pad form-grid"><h2>Purchase with wallet</h2><div class="toolbar"><label class="field"><span>Find a plan</span><input v-model="planQ" @keydown.enter="planPage=1;loadPlans()" /></label><button class="btn secondary" @click="planPage=1;loadPlans()">Find plans</button></div><p v-if="planState==='loading'">Loading…</p><p v-else-if="planState==='ready' && !plans.length">No plans found.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Plan</th><th>Quota</th><th>Duration</th><th>Price</th></tr></thead><tbody><tr v-for="row in plans" :key="row.id" tabindex="0" :class="{'selected-row':selectedPlan?.id===row.id}" @click="choosePlan(row)" @keydown.enter="choosePlan(row)"><td>{{ row.title }}</td><td>{{ (row.quota_bytes === null ? "Unlimited" : faNumber(row.quota_bytes/1024**3)) }} GiB</td><td>{{ row.duration_days === null ? "No expiry" : faNumber(row.duration_days) + " days" }}</td><td>{{ toman(row.price_rial) }}</td></tr></tbody></table></div><div class="pager"><button :disabled="planPage<=1" @click="planPage--;loadPlans()">‹</button><span>{{ faNumber(planPage) }}</span><button :disabled="planPage>=planPages" @click="planPage++;loadPlans()">›</button></div><form v-if="selectedPlan" class="form-grid" @submit.prevent="purchase"><h3>Purchase {{ selectedPlan.title }}</h3><PlanIpAllowance :policy="selectedPlan.effective_ip_policy" :configured="selectedPlan.ip_limit"/><button type="button" class="btn secondary" :disabled="busy" @click="beginCheckout">Automated checkout</button><p v-if="quoteBusy">Loading your price…</p><section v-if="selectedQuote" class="hint-box" aria-label="Personalized purchase quote"><p>Base price: {{toman(selectedQuote.base_price_rial)}}</p><p>Final discount: {{toman(selectedQuote.discount_rial)}}</p><p><strong>Wallet charge: {{toman(selectedQuote.price_rial)}}</strong></p><p>Renewal price under current rules: {{toman(selectedQuote.renewal_price_rial)}}</p><p v-if="selectedQuote.tier_code">Tier: {{selectedQuote.tier_code}}</p><p v-if="selectedQuote.first_purchase_discount_bps">First purchase discount eligibility is included in this quote. The final discount reflects combination rules and discount caps.</p><p>Track delivery in My services.</p></section><button v-if="selectedQuote" type="button" class="btn secondary" :disabled="busy || quoteBusy" @click="loadQuote(selectedPlan.id)">Refresh my price</button><button v-if="!selectedQuote" type="button" class="btn secondary" :disabled="quoteBusy" @click="loadQuote(selectedPlan.id)">Retry price quote</button><label class="check-row"><input v-model="autoRenew" type="checkbox" />Renew automatically when my wallet has sufficient funds</label><button class="btn" :disabled="busy||quoteBusy||!selectedQuote">Confirm wallet purchase</button></form></section>
<section v-if="tab==='plans'" class="card card-pad form-grid" aria-label="Checkout history"><h2>My checkouts</h2><label class="field"><span>Checkout status</span><select v-model="checkoutFilter" @change="checkoutPage=1;loadCheckouts()"><option value="">All statuses</option><option v-for="state in (['awaiting_funding','ready','action_required','purchased','cancelled','expired'] as const)" :key="state" :value="state">{{state.replaceAll('_',' ')}}</option></select></label><button class="btn secondary" @click="loadCheckouts">Refresh checkouts</button><p v-if="checkoutState==='loading'">Loading checkouts…</p><p v-if="checkoutState==='error'">Checkouts could not be loaded. Retry to view saved purchases.</p><p v-if="checkoutState==='ready'&&!checkouts.length">No checkouts yet.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Checkout</th><th>Plan</th><th>Price</th><th>Status</th><th>Expires</th><th>Action</th></tr></thead><tbody><tr v-for="row in checkouts" :key="row.id"><td>{{row.id}}</td><td>{{row.plan_id}}</td><td>{{toman(row.price_rial)}}</td><td>{{row.state.replaceAll('_',' ')}}</td><td>{{faDate(row.expires_at)}}</td><td><button class="btn small secondary" @click="resumeCheckout(row)">Open checkout #{{row.id}}</button></td></tr></tbody></table></div><div class="pager"><button :disabled="checkoutPage<=1" @click="checkoutPage--;loadCheckouts()">Previous checkouts</button><span>{{checkoutPage}}</span><button :disabled="checkoutPage>=checkoutPages" @click="checkoutPage++;loadCheckouts()">Next checkouts</button></div></section><CustomerCheckoutModal :open="checkoutOpen" :plan="selectedPlan" :checkout-id="checkoutId" :preferences="preferences" @close="checkoutOpen=false" @saved="checkoutSaved" />
<section v-if="tab==='subscriptions'" class="card card-pad form-grid"><h2>My services</h2><button class="btn secondary" @click="loadSubscriptions">Refresh services</button><p v-if="subscriptionState==='loading'">Loading…</p><p v-else-if="subscriptionState==='ready' && !subscriptions.length">You do not have a service yet.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Status</th><th>Usage</th><th>Expires</th><th>Renewal</th></tr></thead><tbody><tr v-for="row in subscriptions" :key="row.id" tabindex="0" :class="{'selected-row':selectedSubscription?.id===row.id}" @click="showDelivery(row)" @keydown.enter="showDelivery(row)"><td>{{ faNumber(row.id) }}</td><td>{{ statuses[row.status]??'Needs review' }}</td><td>{{ faNumber(row.used_bytes/1024**3) }} / {{ (row.quota_bytes === null ? "Unlimited" : faNumber(row.quota_bytes/1024**3)) }} GiB</td><td>{{ faDate(row.expires_at) }}</td><td>{{ row.auto_renew?'Enabled':'Disabled' }}</td></tr></tbody></table></div><div class="pager"><button :disabled="subscriptionPage<=1" @click="subscriptionPage--;loadSubscriptions()">‹</button><span>{{ faNumber(subscriptionPage) }}</span><button :disabled="subscriptionPage>=subscriptionPages" @click="subscriptionPage++;loadSubscriptions()">›</button></div><section v-if="selectedSubscription" class="form-grid"><h3>Subscription {{ faNumber(selectedSubscription.id) }}</h3><IpPolicySummary :purchased="selectedSubscription.purchased_ip_policy" :effective="selectedSubscription.effective_ip_policy"/><RouterLink class="btn secondary" :to="{path:'/account/support',query:{subscription_id:selectedSubscription.id}}">Get help with this service</RouterLink><p v-if="selectedSubscription.entitlement_kind==='trial'" class="badge">Trial · automatic renewal unavailable</p><button v-else class="btn secondary" :disabled="busy" @click="renewal">{{ selectedSubscription.auto_renew?'Disable automatic renewal':'Enable automatic renewal' }}</button><CustomerRenewalEligibility :subscription-id="selectedSubscription.id" :refresh-key="selectedSubscription.auto_renew" /><template v-if="delivery"><p v-if="delivery.status === 'customer_hold'">Service access is suspended by an administrator. Your wallet balance is preserved.</p><a v-if="delivery.portal_url" class="btn" :href="delivery.portal_url">Download Configurations</a><p v-else>Configuration delivery is unavailable for the current service state.</p><a v-if="delivery.feed_url" :href="delivery.feed_url" class="private-link" dir="ltr">{{ delivery.feed_url }}</a><p v-if="delivery.can_rotate_link">Rotating the URL invalidates the previous link.</p><button v-if="delivery.can_rotate_link" class="btn secondary" :disabled="busy" @click="rotate">Revoke previous URL and create a new link</button></template></section></section>
<section v-if="tab==='ledger'" class="card card-pad form-grid"><h2>Wallet activity</h2><button class="btn secondary" @click="loadLedger">Refresh activity</button><p v-if="ledgerState==='loading'">Loading…</p><p v-else-if="ledgerState==='ready' && !ledger.length">No wallet activity yet.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Description</th><th>Amount</th><th>Balance</th></tr></thead><tbody><tr v-for="row in ledger" :key="row.id"><td>{{ faDate(row.created_at) }}</td><td>{{ reasons[row.reason]??'Actions Wallet' }}</td><td>{{ toman(row.amount_rial) }}</td><td>{{ toman(row.balance_after_rial) }}</td></tr></tbody></table></div><div class="pager"><button :disabled="ledgerPage<=1" @click="ledgerPage--;loadLedger()">‹</button><span>{{ faNumber(ledgerPage) }}</span><button :disabled="ledgerPage>=ledgerPages" @click="ledgerPage++;loadLedger()">›</button></div></section><p v-if="preferences?.support_handle">Support: {{ preferences.support_handle }}</p></main></template>
<style scoped>.customer-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}.private-link{overflow-wrap:anywhere}.form-grid{min-width:0}</style>
